-- NumPy 2.3.5 oracle; no Python required to replay
local np=require('luaray_core')
assert(np._version=='0.104.0-dev')
local cases=0
local function eq(a,b) assert(a==b, tostring(a).." ~= "..tostring(b));cases=cases+1 end
local function eqnum(a,b) assert(a==b or (a~=a and b~=b), tostring(a).." ~= "..tostring(b));cases=cases+1 end
do local r=np.random.default_rng(0); local v=r:gumbel(0.0,1.0,nil)
eqnum(v,-0.013159932702447984)
eq(r:raw_hex(),"4510bdf882d9d721")
end
do local r=np.random.default_rng(0); local v=r:gumbel(0.0,1.0,{})
eq(v.dtype,"float64")
